{% macro filter_increasing_stage_dates(cte_name, partition_by, order_by, date_col) %}
    -- Generated by macro: filter_increasing_stage_dates
    -- Filters out records where the date is earlier than any previous stage's date
    -- Uses a running maximum to ensure strict temporal ordering
    SELECT *
    FROM (
        SELECT
            *,
            MAX({{ date_col }}) OVER (
                PARTITION BY {{ partition_by }} 
                ORDER BY {{ order_by }}
                ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
            ) as max_prev_date
        FROM {{ cte_name }}
    ) validation
    WHERE {{ date_col }} >= max_prev_date OR max_prev_date IS NULL
{% endmacro %}
